// =============================================================
// Hermes → Noellyne Bet: map quant picks to the app's daily_picks feed
// Attach this node right after "Quant Model v3.1" (same input the
// "Format Message" node already receives). Telegram stays as-is.
// =============================================================
const up = $('Quant Model v3.1').first().json || {};
const picks = [...(up.footballPicks || []), ...(up.basketballPicks || [])];
if (!picks.length) return [];

const strip = (v) => String(v ?? '')
  .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{2B00}-\u{2BFF}]/gu, '')
  .replace(/\s+/g, ' ')
  .trim();

function slipCode(p) {
  const s = `${p.match}|${p.market}`.toLowerCase();
  let h = 2166136261;
  for (const ch of s) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619) >>> 0; }
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let out = '';
  let n = h;
  for (let i = 0; i < 5; i++) { out += alphabet[n % alphabet.length]; n = Math.floor(n / alphabet.length); }
  return `NLY-${out}`;
}

function tagsFor(p) {
  const tags = [];
  const market = String(p.market || '').toUpperCase();
  const prob = Number(p.probPct) || 0;
  const odds = Number(p.odds) || 0;
  if (prob >= 80) tags.push('sure2+');
  if (String(p.tier || '').includes('STRONG')) tags.push('strong');
  if (market.includes('OVER')) tags.push('over2.5');
  if (market.includes('UNDER')) tags.push('under2.5');
  if (market.includes('DC') || market.includes('BTTS') || market.includes('BOTH TEAMS')) tags.push('btts');
  if (odds >= 2) tags.push('high-odds');
  return tags;
}

const nowIso = new Date().toISOString();
const rows = picks
  .filter((p) => p && p.match && p.market)
  .map((p) => ({
    match: strip(p.match),
    league: strip(p.league) || 'Football',
    pick: strip(p.market),
    odds: Math.round((Number(p.odds) || 0) * 100) / 100,
    confidence: Math.max(0, Math.min(100, Math.round(Number(p.probPct) || 0))),
    reasoning: strip(
      [p.explain, p.injuryNote ? `Injury Guard: ${p.injuryNote}` : '']
        .filter(Boolean)
        .join(' — ')
    ).slice(0, 600),
    kickoff_time: p.kickoffISO || nowIso,
    tags: tagsFor(p),
    slip_code: slipCode(p),
    sport: p.sport === 'basketball' ? 'basketball' : 'football',
    tier: strip(p.tier),
    units: Number(p.units) || 0,
    edge_pct: Number(p.edgePct) || 0,
    injury_note: strip(p.injuryNote || ''),
    status: 'published',
    source: 'hermes-n8n',
  }));

return rows.map((row) => ({ json: row }));
